from itertools import product
# 명제 논리: 식은 튜플, 모델은 dict. I(f, w) 와 M(f) 를 그대로 구현
def I(f, w):
    if isinstance(f, str): return w[f]
    op, *a = f
    if op == "not": return not I(a[0], w)
    if op == "and": return I(a[0], w) and I(a[1], w)
    if op == "or":  return I(a[0], w) or I(a[1], w)
    if op == "->":  return (not I(a[0], w)) or I(a[1], w)
    if op == "<->": return I(a[0], w) == I(a[1], w)
SYMS = ["Rain", "Wet"]
def M(fs):  # 식 집합(KB)을 만족하는 모델 목록
    ws = [dict(zip(SYMS, v)) for v in product([False, True], repeat=len(SYMS))]
    return [w for w in ws if all(I(f, w) for f in fs)]
def relation(kb, f):
    old, new = M(kb), M(kb + [f])
    if not new: return "contradiction"
    if new == old: return "entailment"
    return "contingency"
kb = ["Rain", ("->", "Rain", "Wet")]
print(I(("and", "Rain", ("not", "Wet")), {"Rain": True, "Wet": False}))  # True
print(M(kb))                                    # [{'Rain': True, 'Wet': True}]
print(relation(kb, "Wet"), relation(kb, ("not", "Wet")), relation(["Rain"], "Wet"))

# '모든 학생은 산수를 안다'를 명제 논리로 적으면 식 길이가 학생 수에 비례한다
def propositional(names):
    parts = [f"({n}IsStudent -> {n}KnowsArithmetic)" for n in names]
    return " & ".join(parts)
for n in [2, 10, 1000]:
    names = [f"S{i}" for i in range(n)]
    print(n, "명", "명제 식 길이:", len(propositional(names)))
fol = "forall x. Student(x) -> Knows(x, arithmetic)"
print("1차 논리 식 길이:", len(fol), "(학생 수와 무관)")
print(propositional(["Alice", "Bob"]))

# 1차 논리 구문 검사기: 항(대상)과 식(참·거짓)을 가른다
CONST, VARS = {"alice", "bob", "arithmetic"}, {"x", "y"}
FUNCS = {"father": 1, "add": 2}                  # 항 -> 항
PREDS = {"Snowing": 0, "Student": 1, "Knows": 2}  # 항 -> 참/거짓
def is_term(t):
    if isinstance(t, str): return t in CONST or t in VARS
    f, *args = t
    return FUNCS.get(f) == len(args) and all(is_term(a) for a in args)
def is_formula(f):
    op, *a = f if isinstance(f, tuple) else (f,)
    if op in PREDS: return PREDS[op] == len(a) and all(is_term(x) for x in a)
    if op == "not": return is_formula(a[0])
    if op in ("and", "or", "->"): return all(is_formula(x) for x in a)
    if op in ("forall", "exists"): return a[0] in VARS and is_formula(a[1])
    return False
tests = {
    "forall x. Student(x) -> Knows(x, arithmetic)":
        ("forall", "x", ("->", ("Student", "x"), ("Knows", "x", "arithmetic"))),
    "father(x)": ("father", "x"),
    "Knows(Student, arithmetic)": ("Knows", "Student", "arithmetic"),
    "Knows(father(father(alice)), arithmetic)":
        ("Knows", ("father", ("father", "alice")), "arithmetic"),
}
for s, f in tests.items():
    print(f"{s:45s} 식? {is_formula(f)}   항? {is_term(f)}")

# 1차 논리 모델 = 영역(대상 집합) + 해석(기호 -> 대상)
domain = ["o1", "o2", "o3"]
consts = {"alice": "o1", "bob": "o2", "robert": "o2", "arithmetic": "o3"}
funcs = {"father": {"o1": "o2"}}
preds = {"Knows": {("o1", "o3")}, "Student": {("o1",)}}   # 참인 튜플만 적는다
def term(t, sub):
    if isinstance(t, str):
        return sub[t] if t in sub else consts[t]
    f, arg = t                        # 함수는 1항(father)만 예로 든다
    return funcs[f][term(arg, sub)]
def I(f, sub={}):
    op, *a = f
    if op == "forall": return all(I(a[1], {**sub, a[0]: o}) for o in domain)
    if op == "exists": return any(I(a[1], {**sub, a[0]: o}) for o in domain)
    if op == "not": return not I(a[0], sub)
    if op == "and": return I(a[0], sub) and I(a[1], sub)
    if op == "->":  return (not I(a[0], sub)) or I(a[1], sub)
    return tuple(term(x, sub) for x in a) in preds[op]     # 원자식
print(I(("Knows", "alice", "arithmetic")))                        # True
print(I(("forall", "x", ("Knows", "x", "arithmetic"))))           # False
print(I(("forall", "x", ("->", ("Student", "x"), ("Knows", "x", "arithmetic")))))  # True
print(I(("Knows", ("father", "alice"), "arithmetic")), I(("Knows", "bob", "arithmetic")))

# 치환(substitute)과 단일화(unify). 소문자 x,y,z,… 한 글자는 변수, 나머지는 상수
is_var = lambda t: isinstance(t, str) and t in ("x", "y", "z", "u", "v")
def substitute(t, s):
    if is_var(t): return substitute(s[t], s) if t in s else t
    if isinstance(t, tuple): return tuple(substitute(a, s) for a in t)
    return t
def occurs(v, t, s):
    t = substitute(t, s)
    return t == v or (isinstance(t, tuple) and any(occurs(v, a, s) for a in t))
def unify(a, b, s):
    if s is None: return None
    a, b = substitute(a, s), substitute(b, s)
    if a == b: return s
    if is_var(a): return None if occurs(a, b, s) else {**s, a: b}
    if is_var(b): return unify(b, a, s)
    if isinstance(a, tuple) and isinstance(b, tuple) and len(a) == len(b) and a[0] == b[0]:
        for x, y in zip(a[1:], b[1:]):
            s = unify(x, y, s)
        return s
    return None
if __name__ == "__main__":
    print(substitute(("Knows", "x", "y"), {"x": "alice", "y": "cs221"}))
    print(unify(("Knows", "x", "y"), ("Knows", "alice", "bob"), {}))
    print(unify(("Knows", "alice", "y"), ("Knows", "x", "z"), {}))
    print(unify(("Knows", "alice", "y"), ("Knows", "bob", "z"), {}))      # None
    print(unify(("P", "x", "x"), ("P", "alice", "bob"), {}))              # None
    print(unify(("Knows", "x", ("father", "x")), ("Knows", ("father", "y"), "y"), {}))  # None(발생 검사)

