# 단일화를 쓴 modus ponens 를 더 나올 게 없을 때까지 되풀이(전방 연쇄)
from c10 import unify, substitute
facts = {("Takes", "alice", "cs221"), ("Covers", "cs221", "logic"),
         ("Takes", "bob", "cs229"), ("Covers", "cs229", "ml"), ("Covers", "cs221", "search")}
rules = [([("Takes", "x", "y"), ("Covers", "y", "z")], ("Knows", "x", "z"))]
def match(body, s):                   # 몸통의 원자식을 차례로 사실과 단일화
    if not body:
        yield s; return
    for f in sorted(facts):
        s2 = unify(body[0], f, dict(s))
        if s2 is not None:
            yield from match(body[1:], s2)
new = True
while new:
    new = False
    for body, head in rules:
        for th in list(match(body, {})):
            b = substitute(head, th)
            if b not in facts:
                print("유도:", b, " θ =", th); facts.add(b); new = True

